<script>
(() => {
  const grid = document.getElementById('pg-grid');
  const q = document.getElementById('pg-q');
  const live = document.getElementById('pg-live');
  const items = [...grid.querySelectorAll('li[data-for~="ready"]')];

  function setState(s) {
    grid.dataset.state = s;
    grid.setAttribute('aria-busy', String(s === 'loading'));
  }

  function applyFilter() {
    const term = q.value.trim().toLowerCase();
    let shown = 0;
    items.forEach(li => {
      const match = li.querySelector('.pc').dataset.name.toLowerCase().includes(term);
      li.dataset.hidden = String(!match);
      if (match) shown++;
    });
    if (shown === 0) {
      document.getElementById('pg-empty-text').textContent = `No projects match "${q.value.trim()}".`;
      setState('empty');
    } else {
      setState('ready');
    }
    live.textContent = `${shown} project${shown === 1 ? '' : 's'} shown`;
  }

  q.addEventListener('input', applyFilter);

  document.getElementById('pg-reset').addEventListener('click', () => {
    q.value = ''; applyFilter(); q.focus();
  });

  grid.addEventListener('click', e => {
    const btn = e.target.closest('.pc-select');
    if (!btn) return;
    const card = btn.closest('.pc');
    if (card.dataset.disabled === 'true') return;
    const on = card.dataset.selected !== 'true';
    card.dataset.selected = String(on);
    btn.setAttribute('aria-pressed', String(on));
  });

  // Demo wiring: replace with your real fetch.
  document.querySelector('[data-demo="loading"]').addEventListener('click', () => {
    setState('loading'); setTimeout(applyFilter, 1500);
  });
  document.querySelector('[data-demo="error"]').addEventListener('click', () => setState('error'));
  document.getElementById('pg-retry').addEventListener('click', () => {
    setState('loading'); setTimeout(applyFilter, 800);
  });
})();
</script>
</body>
